          { kind: "fill", promptUk: "Допишіть параметр насіння генератора fast-check", promptEn: "Fill in the fast-check generator seed parameter", language: "javascript", code: "fc.configureGlobal({ ___: 12345 })", accepted: ["seed"], caseSensitive: true, explanationUk: "Зберігайте seed і повідомлений path для повторення конкретного контрприкладу; зовнішній стан також має бути контрольованим.", explanationEn: "Record the seed and reported path to replay a particular counterexample; external state must also be controlled." },
          { kind: "read", promptUk: "Що зробити з юніт-тестом, який ходить у реальний платіжний SaaS?", promptEn: "What should you do with a unit test that hits a real payments SaaS?", language: "javascript", code: "await fetch('https://pay.example/charge')", options: ["винести з юнітів: мок/контракт; rerun не лікує чужий простій", "додати три rerun і вважати це нормою", "збільшити sleep до 10 секунд", "вимкнути затвердження карток"], optionsEn: ["Use a mock for unit tests and test the external integration separately", "Add three retries and treat that as normal", "Increase sleep to ten seconds", "Disable card approval"], correctIndex: 0, explanationUk: "Шар тесту має відповідати залежності.", explanationEn: "The test layer must match the dependency." },
          { kind: "mcq", promptUk: "Елемент уже є в DOM, але ще прихований. Якого результату слід чекати, якщо вимога — його видимість?", promptEn: "The element is already in the DOM but still hidden. What should the test wait for if visibility is required?", options: ["успішної перевірки видимості з обмеженим часом очікування", "лише існування вузла в DOM", "рівно одну секунду без перевірки", "зміни насіння генератора"], optionsEn: ["A successful visibility assertion within a bounded timeout", "Only the existence of a DOM node", "Exactly one second without an assertion", "A change of random seed"], correctIndex: 0, explanationUk: "Наявність і видимість — різні умови.", explanationEn: "Presence and visibility are different conditions." }
